# CORE-02 requirements reference: stdlib only; no production/test module imports.
import copy
import hashlib
import json

ACTOR, SPACE = "actor:trial", "space:trial"
WIDTH, HEIGHT, CELL_MM = 3, 3, 1000
BLOCKED = (1,)
SEED, BRANCH, STREAM = "0" * 64, "0" * 32, "1" * 32

def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")

def frame(*tokens):
    result = bytearray()
    for token in tokens:
        raw = token.encode("utf-8")
        result.extend(len(raw).to_bytes(4, "big"))
        result.extend(raw)
    return bytes(result)

def tagged(tag, value):
    return hashlib.sha256(frame(tag, canonical(value).decode("utf-8"))).hexdigest()

def key(kind):
    return {"kind": "trial." + kind, "version": 1}

def integer_field(owner, unit, minimum, maximum):
    return {"owner": owner, "storage": "CORE", "tier": "A", "unit": unit,
            "scale": 1, "minimum": minimum, "maximum": maximum}

schema_document = {"version": 1, "unknown_fields": "reject", "bool_as_integer": "reject",
 "components": [
  {"schema": key("map"), "fields": {
   "width": integer_field("system.bootstrap", "cell_count", 3, 3),
   "height": integer_field("system.bootstrap", "cell_count", 3, 3),
   "cell_mm": integer_field("system.bootstrap", "mm", 1000, 1000),
   "blocked_cells": {**integer_field("system.bootstrap", "cell", 0, 8), "collection_cap": 1}}},
  {"schema": key("position"), "fields": {
   "cell": integer_field("trial.movement", "cell", 0, 8),
   "space_id": {"owner": "system.bootstrap", "storage": "CORE", "tier": "A", "unit": "entity_id", "scale": 1}}}],
 "payloads": [
  {"schema": key("move"), "fields": ["dx", "dz"]},
  {"schema": key("move-blocked"), "fields": ["actor_id", "space_id", "from_cell", "dx", "dz", "reason"]},
  {"schema": key("move-cue"), "fields": ["actor_id", "space_id", "from_cell", "to_cell", "from_x_mm", "from_z_mm", "to_x_mm", "to_z_mm", "result"]},
  {"schema": key("moved"), "fields": ["actor_id", "space_id", "from_cell", "to_cell"]},
  {"schema": key("position-delta"), "fields": ["entity_id", "before_cell", "after_cell"]},
  {"schema": key("position-patch"), "fields": ["cell"]}]}
rules_document = {"version": 1, "actor_id": ACTOR, "space_id": SPACE,
 "width": WIDTH, "height": HEIGHT, "cell_mm": CELL_MM, "blocked_cells": list(BLOCKED),
 "initial_cell": 0, "duration_seconds": 1, "cardinal_directions": [[-1,0],[0,-1],[0,1],[1,0]],
 "blocked_attempt_consumes_time": True, "boundary_precedes_occupancy": True,
 "record_only": True, "rng_purposes": []}
schedule_document = {"version": 1, "nodes": [{
 "phase": "RESOLVE", "engine_id": "trial.movement", "lane": "A",
 "reads": ["trial.map.blocked_cells", "trial.map.height", "trial.map.width", "trial.position.cell", "trial.position.space_id"],
 "writes": ["trial.position.cell"], "depends_on": [], "action_kinds": [key("move")],
 "on_matching_events": False, "every_tick": False, "emits": [key("move-blocked"), key("moved")],
 "consumes": [], "cost_class": "local"}]}
SCHEMA_HASH = tagged("schema/v1", schema_document)
RULES_HASH = tagged("rules/v1", rules_document)
SCHEDULE_HASH = tagged("schedule/v1", schedule_document)
CATALOG = tagged("gameplay-catalog/v1", [])
WORLD = "w1-" + hashlib.sha256(frame("world-id/v1", SEED, RULES_HASH, CATALOG)).hexdigest()
pins = {"schema_fingerprint": SCHEMA_HASH, "rules_fingerprint": RULES_HASH, "schedule_fingerprint": SCHEDULE_HASH,
 "rng_version": "sha256-counter-v1", "hash_version": "sha256-core-tree-v1", "gameplay_catalog_hash": CATALOG, "gameplay_packages": []}

def core(tick, cell):
    return {"world_id": WORLD, "world_seed_hex": SEED, "tick": tick,
     "components": [
      {"schema": key("map"), "entity_id": SPACE, "fields": {"width": WIDTH, "height": HEIGHT, "cell_mm": CELL_MM, "blocked_cells": list(BLOCKED)}},
      {"schema": key("position"), "entity_id": ACTOR, "fields": {"space_id": SPACE, "cell": cell}}],
     "pending": [], "pins": pins}

def core_hash(document):
    leaves = [{"schema": c["schema"], "entity_id": c["entity_id"], "hash": tagged("component/v1", c)} for c in document["components"]]
    return tagged("core-root/v1", {**document, "components": leaves})

def command(sequence, dx, dz, revision):
    return {"command_id": f"c1:{BRANCH}:{STREAM}:{sequence}", "actor_id": ACTOR, "expected_revision": revision,
            "schema": key("move"), "payload": {"dx": dx, "dz": dz}}

def transition(cell, dx, dz):
    assert type(cell) is int and 0 <= cell <= 8 and cell not in BLOCKED
    assert type(dx) is int and type(dz) is int and abs(dx) + abs(dz) == 1
    x, z = cell % WIDTH + dx, cell // WIDTH + dz
    if not (0 <= x < WIDTH and 0 <= z < HEIGHT):
        return cell, "boundary"
    target = z * WIDTH + x
    if target in BLOCKED:
        return cell, "occupied"
    return target, "moved"

def event_header(tick, schema):
    identifier = "e1-" + hashlib.sha256(frame("event-id/v1", WORLD, str(tick), "RESOLVE", "0", "trial.movement", "0")).hexdigest()
    return {"event_id": identifier, "type_key": schema, "producer_id": "trial.movement", "occurred_at": tick,
            "phase": "RESOLVE", "wave": 0, "producer_rank": 0, "sequence": 0, "caused_by": [], "degraded": []}

def make_cue(fact, before, after, result):
    event_id = fact["header"]["event_id"]
    identifier = "p1-" + hashlib.sha256(frame("cue-id/v1", event_id, "trial.presenter", "0")).hexdigest()
    return {"header": {"event_id": identifier, "type_key": key("move-cue"), "producer_id": "trial.presenter",
     "occurred_at": fact["header"]["occurred_at"], "phase": "PRESENT", "wave": 0, "producer_rank": 0, "sequence": 0,
     "caused_by": [event_id], "degraded": []}, "payload": {"actor_id": ACTOR, "space_id": SPACE, "from_cell": before, "to_cell": after,
     "from_x_mm": before % WIDTH * CELL_MM, "from_z_mm": before // WIDTH * CELL_MM,
     "to_x_mm": after % WIDTH * CELL_MM, "to_z_mm": after // WIDTH * CELL_MM, "result": result},
     "priority": "important", "coalesce_policy": "keep_all", "coalesce_key": ""}

receipts = []
revision, tick, cell, high_water = 0, 0, 0, 0

def protocol():
    return {"branch_id": BRANCH, "revision": revision, "streams": [{"stream_id": STREAM, "actor_id": ACTOR,
            "highest_committed_sequence": high_water, "status": "active"}], "receipts": copy.deepcopy(receipts)}

initial_core, initial_protocol = core(0, 0), protocol()
header = {"world_id": WORLD, "world_seed_hex": SEED, "initial_core_hash": core_hash(initial_core),
 "initial_protocol_hash": tagged("protocol/v1", initial_protocol), "schema_fingerprint": SCHEMA_HASH,
 "rules_fingerprint": RULES_HASH, "schedule_fingerprint": SCHEDULE_HASH,
 "rng_version": pins["rng_version"], "hash_version": pins["hash_version"], "gameplay_packages": [], "build_artifacts": []}
steps, publications = [], []
flow = [(1,1,0,0), (2,0,1,1), (3,1,0,2), (4,0,-1,3), (5,-1,0,4), (6,-1,0,5), (1,1,0,0), (7,0,1,0), (1,0,1,0), (7,0,1,6)]
for index, (sequence, dx, dz, expected_revision) in enumerate(flow):
    cmd = command(sequence, dx, dz, expected_revision)
    facts, cues, diagnostics, diff = [], [], [], None
    if index == 6:
        outcome = {"kind": "committed", "receipt": copy.deepcopy(receipts[0]["receipt"])}
        diagnostics = [{"code": "RESYNC_REQUIRED", "message_key": "error.resync_required"}]
    elif index in (7,8):
        code = "STALE_REVISION" if index == 7 else "COMMAND_ID_CONFLICT"
        outcome = {"kind": "rejected", "failure": {"code": code, "message_key": "error." + code.lower()}, "current_revision": revision}
    else:
        before = cell
        cell, result = transition(cell, dx, dz)
        previous = revision
        revision += 1
        tick += 1
        high_water = sequence
        receipt = {"command_id": cmd["command_id"], "previous_revision": previous, "revision": revision, "tick": tick, "core_hash": core_hash(core(tick, cell))}
        outcome = {"kind": "committed", "receipt": receipt}
        receipts.append({"command": cmd, "command_fingerprint": tagged("command/v1", {k: v for k,v in cmd.items() if k != "command_id"}), "receipt": receipt})
        if result == "moved":
            fact = {"header": event_header(tick, key("moved")), "due_tick": tick,
                    "payload": {"actor_id": ACTOR, "space_id": SPACE, "from_cell": before, "to_cell": cell}}
            changes = [{"schema": key("position-delta"), "entity_id": ACTOR, "before_cell": before, "after_cell": cell}]
        else:
            fact = {"header": event_header(tick, key("move-blocked")), "due_tick": tick,
                    "payload": {"actor_id": ACTOR, "space_id": SPACE, "from_cell": before, "dx": dx, "dz": dz, "reason": result}}
            changes = []
        facts = [fact]
        cues = [make_cue(fact, before, cell, result)]
        diff = {"receipt": receipt, "changes": changes}
    core_doc, protocol_doc = core(tick, cell), protocol()
    steps.append({"command": cmd, "outcome": copy.deepcopy(outcome), "core_hash": core_hash(core_doc), "protocol_hash": tagged("protocol/v1", protocol_doc),
     "facts_hash": tagged("turn-facts/v1", facts), "diff_hash": tagged("turn-diff/v1", diff),
     "witness": {"core": core_doc, "protocol": protocol_doc, "facts": copy.deepcopy(facts), "diff": copy.deepcopy(diff)}})
    publications.append({"outcome": copy.deepcopy(outcome), "facts": copy.deepcopy(facts), "diff": copy.deepcopy(diff), "cues": copy.deepcopy(cues), "diagnostics": diagnostics})
expected_fixture = {"format_version": 1, "initial_core": initial_core, "initial_protocol": initial_protocol, "trace": {"header": header, "steps": steps}}

# A valid adjacent alternative 3->6 for step3 vs required Right 3->4; self-consistent witnesses.
wrong = copy.deepcopy(expected_fixture)
wrong["trace"]["steps"] = wrong["trace"]["steps"][:3]
last = wrong["trace"]["steps"][2]
witness = last["witness"]
witness["core"]["components"][1]["fields"]["cell"] = 6
last["core_hash"] = core_hash(witness["core"])
for receipt in (last["outcome"]["receipt"], witness["protocol"]["receipts"][-1]["receipt"], witness["diff"]["receipt"]):
    receipt["core_hash"] = last["core_hash"]
witness["diff"]["changes"][0]["after_cell"] = 6
witness["facts"][0]["payload"]["to_cell"] = 6
for category, tag in (("protocol","protocol/v1"),("facts","turn-facts/v1"),("diff","turn-diff/v1")):
    last[category+"_hash"] = tagged(tag, witness[category])

movement_vectors = []
for old in (0,2,3,4,5,6,7,8):
    for dx,dz in ((-1,0),(0,-1),(0,1),(1,0)):
        new,result = transition(old,dx,dz)
        movement_vectors.append({"from_cell":old,"dx":dx,"dz":dz,"to_cell":new,"result":result,
                                "tick_increment":1,"revision_increment":1,"delta_count":int(result=="moved"),"fact_count":1,"cue_count":1})
coordinates = [{"cell":i,"x_mm":i%3*1000,"z_mm":i//3*1000} for i in range(9)]
literal_documents = []
for name, tag, doc in (("schema","schema/v1",schema_document),("rules","rules/v1",rules_document),
                       ("schedule","schedule/v1",schedule_document),("map","component/v1",initial_core["components"][0]),
                       ("position0","component/v1",initial_core["components"][1]),
                       ("command1","command/v1",{k:v for k,v in steps[0]["command"].items() if k != "command_id"})):
    raw=canonical(doc)
    literal_documents.append({"name":name,"tag":tag,"document":doc,"utf8":raw.decode("utf-8"),"utf8_hex":raw.hex(),"sha256":tagged(tag,doc)})
result = {"schema_document":schema_document,"rules_document":rules_document,"schedule_document":schedule_document,
 "literal_documents":literal_documents,"movement_vectors":movement_vectors,"coordinates":coordinates,
 "expected_fixture":expected_fixture,"expected_fixture_canonical_sha256":hashlib.sha256(canonical(expected_fixture)).hexdigest(),
 "expected_publications":publications,"negative_self_consistent_step3_fixture":wrong,
 "negative_expected_first_mismatch":{"step_index":2,"path":"$core.components[1].fields.cell","expected":"6","actual":"4"}}
